package com.siestech.booksharing.Practical;
import android.content.Intent; import android.os.Bundle; import android.speech.RecognizerIntent; import android.speech.tts.TextToSpeech; import android.widget.EditText; import android.widget.Toast; import androidx.annotation.Nullable; import androidx.appcompat.app.AppCompatActivity; import com.siestech.booksharing.R; import java.util.ArrayList; import java.util.Locale;
public class TtsActivity extends AppCompatActivity{
 private TextToSpeech tts; private EditText input; private final int VOICE=71;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_tts);input=findViewById(R.id.textInput);tts=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS)tts.setLanguage(Locale.ENGLISH);});findViewById(R.id.speakBtn).setOnClickListener(v->{String x=input.getText().toString().trim();if(x.isEmpty())Toast.makeText(this,"Enter text",Toast.LENGTH_SHORT).show();else tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"borrowbox");});findViewById(R.id.stopBtn).setOnClickListener(v->tts.stop());findViewById(R.id.listenBtn).setOnClickListener(v->{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.getDefault());try{startActivityForResult(i,VOICE);}catch(Exception e){Toast.makeText(this,"Speech recognition not available",Toast.LENGTH_SHORT).show();}});}
 @Override protected void onDestroy(){tts.stop();tts.shutdown();super.onDestroy();}
 @Override protected void onActivityResult(int r,int c,@Nullable Intent d){super.onActivityResult(r,c,d);if(r==VOICE&&c==RESULT_OK&&d!=null){ArrayList<String> a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty())input.setText(a.get(0));}}
}
